class Solution {
public:
    int maxScore(vector<int>& nums) {
        int n = nums.size();
        vector<int> dp(n, 0);
        for (int i = n - 2; i >= 0; --i) {
            int best = 0;
            for (int j = i + 1; j < n; ++j) {
                best = max(best, (j - i) * nums[j] + dp[j]);
            }
            dp[i] = best;
        }
        return dp[0];
    }
};

class Solution {
    public int maxScore(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n];
        for (int i = n - 2; i >= 0; --i) {
            int best = 0;
            for (int j = i + 1; j < n; ++j) {
                best = Math.max(best, (j - i) * nums[j] + dp[j]);
            }
            dp[i] = best;
        }
        return dp[0];
    }
}

var maxScore = function(nums) {
    const n = nums.length;
    const dp = new Int32Array(n);
    for (let i = n - 2; i >= 0; --i) {
        let best = 0;
        for (let j = i + 1; j < n; ++j) {
            const score = (j - i) * nums[j] + dp[j];
            if (score > best) best = score;
        }
        dp[i] = best;
    }
    return dp[0];
};
